"""Atlas de los viajes de Pablo: lugares (Escritura · Arqueología · Hoy), tramos del camino y rutas antiguas.

«biblia» admite claves de los pasajes de datos.py (se resuelven con su traducción) o pares [cita, texto].
Cada tramo lleva «medio» («pie»: a pie por calzada o senda; «mar»: en nave) y «viaje» (0 Damasco, 1–3 viajes
misioneros, 4 viaje a Roma): el atlas dibuja los tramos por mar con el pictograma de la nave y los de tierra con
el del caminante. Coordenadas: [lat, lon]. Las identificaciones discutidas se señalan como tales.
"""
from hitos import (JER_DAM, DAM_ARABIA, JER_CES, CES_TARSO, TARSO_ANT, ANT_SEL, SEL_SAL, SAL_PAF, PAF_PER, PER_PIS, PIS_ICO, ICO_LIS, LIS_DER, DER_ATA, ATA_ANT,
                   ANT_DER, DER_TROAS, TROAS_FIL, FIL_TES, TES_BER, BER_ATE, ATE_COR, COR_EFE, EFE_CES, CES_JER_ANT, ANT_EFE, EFE_TROAS, TROAS_MAC, MAC_COR,
                   COR_FIL, FIL_MIL, MIL_TIRO, TIRO_JER, CES_MIRA, MIRA_CRETA, CRETA_MALTA, MALTA_ROMA, EGNATIA, APIA)

def L(id, n, ll, k, actual, biblia=(), arq=(), hoy="", he="", site=None, fuentes=()):
    return {"id": id, "site": site if site is not None else id, "n": n, "he": he, "ll": ll, "k": k, "actual": actual,
            "biblia": list(biblia), "arq": list(arq), "hoy": hoy, "fuentes": list(fuentes)}

